using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
namespace NightLens {
public class SkySite {
    public double Lat {get;set;} public double Lon {get;set;} public double Bortle {get;set;} public double? Sqm {get;set;}
    public double RadiusKm {get;set;}=.5;public string Source {get;set;}="User entry";public bool AreaEstimate {get;set;}
    public static double Distance(double lat,double lon,double lat2,double lon2){double r=Math.PI/180;double a=Math.Pow(Math.Sin((lat2-lat)*r/2),2)+Math.Cos(lat*r)*Math.Cos(lat2*r)*Math.Pow(Math.Sin((lon2-lon)*r/2),2);return 6371*2*Math.Asin(Math.Sqrt(Math.Min(1,a)));}
    public static SkySite At(Settings settings){return (settings.SkySites??new List<SkySite>()).Where(s=>s.Bortle>=1&&s.Bortle<=9&&Distance(settings.Lat,settings.Lon,s.Lat,s.Lon)<=s.RadiusKm).OrderBy(s=>s.AreaEstimate?1:0).ThenBy(s=>Distance(settings.Lat,settings.Lon,s.Lat,s.Lon)).FirstOrDefault();}
}
public static class ImagingGroups {
    static string Compact(string id){return System.Text.RegularExpressions.Regex.Replace((id??"").ToUpperInvariant(),@"[^A-Z0-9]","");}
    public static string Identity(string id){string x=Compact(id);var m=System.Text.RegularExpressions.Regex.Match(x,@"^(NGC|IC|M)0*(\d+)(.*)$");return m.Success?m.Groups[1].Value+m.Groups[2].Value+m.Groups[3].Value:x;}
    public static string Region(Target target){var ids=target.Aliases.Concat(new[]{target.Canonical}).Select(Identity).ToList();if(ids.Any(i=>i=="NGC6992"||i=="NGC6995"))return "Eastern Veil";return null;}
    public static IEnumerable<Pick> Unique(IEnumerable<Pick> source,Rig rig){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var pick in source.OrderByDescending(p=>p.Score)){string region=Region(pick.Target);string key=region??Identity(pick.Target.Canonical??pick.Target.Name);if(!seen.Add(key))continue;if(region=="Eastern Veil"){var old=pick.Target;pick.Target=new Target("Eastern Veil · NGC6992 / NGC6995",old.Type,old.Ra,old.Dec,70,25){Canonical=old.Canonical,CatalogName=old.CatalogName,Magnitude=old.Magnitude,Aliases=new List<string>(old.Aliases)};ObjectInfo.Merge(pick.Target,old);pick.Fit=Math.Max(rig.Width,rig.Height)*60>=70/.9&&Math.Min(rig.Width,rig.Height)*60>=25/.9?"Fits one frame":rig.Mosaic?"Mosaic needed":"Close-up only; full region will not fit";}yield return pick;}}
}
public class CaptureGuide {
    public bool Beginner;public string Difficulty,Sky,Exposure,Gain,Integration,Notes,Details,DeviceSource;public double? SubSeconds,MinHours,MaxHours;
}
public static class CapturePlanning {
    public static string Model(Rig rig){if(rig.CustomDevice)return rig.SmartDevice?"Other smart telescope":"Other camera";var selected=EquipmentLibrary.Find(rig);if(selected!=null)return selected.Smart?(selected.Id=="Seestar S50"?"Seestar S50":"Other smart telescope"):selected.Id=="ASI585MC Pro"?"ASI585MC Pro":"ZWO camera";if(rig.SmartDevice)return "Other smart telescope";if(rig.CaptureModel!="Auto"&&!string.IsNullOrWhiteSpace(rig.CaptureModel))return rig.CaptureModel;string name=(rig.Name??"").ToUpperInvariant(),camera=(rig.Camera??"").ToUpperInvariant();if(name.Contains("SEESTAR")&&name.Contains("S50")&&!name.Contains("PRO"))return "Seestar S50";if(camera.Contains("585")&&camera.Contains("PRO"))return "ASI585MC Pro";if(name.Contains("SEESTAR")||name.Contains("DWARF")||name.Contains("VESPERA")||camera.Contains("BUILT-IN"))return "Other smart telescope";return "Other camera";}
    public static List<double> Allowed(Rig rig){if(EquipmentLibrary.Find(rig)!=null)return EquipmentLibrary.Subs(rig);if(Model(rig)=="Seestar S50")return new List<double>{10,20,30};var result=new List<double>();foreach(string value in (rig.AllowedSubs??"").Split(',')){double n;if(double.TryParse(value.Trim(),NumberStyles.Float,CultureInfo.InvariantCulture,out n)&&n>0&&n<=3600)result.Add(n);}return result.Distinct().OrderBy(n=>n).ToList();}
    public static CaptureGuide For(Pick pick,Rig rig,Settings settings,Night night){var target=pick.Target;var guide=new CaptureGuide();var sky=SkySite.At(settings);double? b=sky==null?(double?)null:sky.Bortle;string model=Model(rig);bool smart=model=="Seestar S50"||model=="Other smart telescope",moon=target.Body==CosineKitty.Body.Moon,planet=target.Body.HasValue&&!moon;bool emission=target.Type=="Emission nebula"||target.Type=="Planetary nebula"||target.Type=="Supernova remnant"||target.Type=="Cluster and nebula";bool filtered=emission&&rig.Filter;bool cluster=target.Type.ToLowerInvariant().Contains("cluster")&&!emission;bool faint=target.Type=="Dark nebula"||target.Type=="Reflection nebula";bool brightCore=target.Aliases.Concat(new[]{target.Canonical}).Select(ImagingGroups.Identity).Any(x=>x=="M42"||x=="NGC1976");bool fits=pick.Fit=="Fits one frame";
        guide.Sky=b.HasValue?"Bortle "+b.Value.ToString("0.0")+(sky.AreaEstimate?" area est.":" site setting"):"Bortle not set for this site";
        bool candidate=cluster&&(target.Magnitude??20)<=8&&target.Major>=5||brightCore||target.Aliases.Concat(new[]{target.Canonical}).Select(ImagingGroups.Identity).Any(x=>new[]{"M27","NGC6853","M81","NGC3031","M8","NGC6523"}.Contains(x));
        guide.Beginner=moon||(candidate&&fits&&pick.Alt>=40&&!faint&&(!b.HasValue||b<=6||cluster||brightCore||filtered));guide.Difficulty=guide.Beginner?"★ Beginner-friendly":"◇ More demanding / unrated";
        guide.Gain=EquipmentLibrary.Gain(rig);var device=EquipmentLibrary.Find(rig);guide.DeviceSource=device==null?"No verified model source selected.":device.Name+" (reviewed "+device.VerifiedOn+")\n"+device.Source;
        double f=Math.Max(2,rig.Focal/rig.Aperture),ratio=Math.Max(.5,Math.Min(3,Math.Pow(f/5,2)));double desired=(b??7)<=3?90:(b??7)<=5?60:(b??7)<=7?30:15;if(filtered)desired*=3;desired*=ratio;if(brightCore||cluster)desired=Math.Min(desired,15*ratio);bool tracked=rig.Mount=="Equatorial / tracker",altaz=(rig.Mount??"").Contains("Alt-az");
        if(moon||planet){guide.Exposure=smart?"Use "+(moon?"Lunar":"Planet")+" mode; app auto exposure":"Short-exposure video; tune to avoid clipping";guide.Gain=smart?"App-controlled (not adjustable)":"Tune in video mode; protect highlights";guide.Integration="Capture 1–3 min video / short bursts";guide.Beginner=moon;}
        else if(rig.Mount=="Not specified"){guide.Exposure="Choose tracking mode in Equipment";guide.Integration="Choose mount before planning a session";}
        else if(smart){var choices=Allowed(rig);if(choices.Count==0){guide.Exposure="Enter app-supported exposure choices";}else if(rig.Mount=="Untracked tripod"){guide.Exposure="Enable telescope tracking first";}else{if(model=="Seestar S50")desired=altaz?10:((b??7)>=7&&!filtered?10:filtered?30:20);else desired=Math.Min(desired,altaz?10:120);double seconds=choices.Where(x=>x<=desired).DefaultIfEmpty(choices.Min()).Max();guide.SubSeconds=seconds;guide.Exposure=seconds.ToString("0.#")+" s per frame";}}
        else {if(!tracked&&!altaz){guide.Exposure="Use ≤1 s test frames; tracking recommended";guide.SubSeconds=1;}else {desired=Math.Min(desired,altaz?10:180);double[] choices={1,2,5,10,15,20,30,45,60,90,120,180};guide.SubSeconds=choices.Where(v=>v<=desired).DefaultIfEmpty(1).Max();guide.Exposure=guide.SubSeconds.Value.ToString("0.#")+" s starting sub-exposure";}}
        if(!moon&&!planet){if(!b.HasValue){guide.Integration="Set site Bortle for total-time guidance";}else {double low=cluster?.3:brightCore?.5:faint?3:emission?1.5:2,high=cluster?.8:brightCore?1.5:faint?6:emission?3:4;double pollution=cluster?1+Math.Max(0,b.Value-4)*.15:filtered?1+Math.Max(0,b.Value-4)*.16:b<=3?1:b<=5?1.5:b<=7?2.5:4;guide.MinHours=Math.Ceiling(low*pollution*ratio*4)/4;guide.MaxHours=Math.Ceiling(high*pollution*ratio*4)/4;guide.Integration=guide.MinHours.Value.ToString("0.##")+"–"+guide.MaxHours.Value.ToString("0.##")+" h accepted integration (est.)";}}
        guide.Notes=EquipmentLibrary.ProfileNote(rig)+" "+(EquipmentLibrary.Find(rig)?.Notes??"")+" Starting plan, not a calibrated optimum. Check a test frame for clipped stars and tracking.";if(filtered)guide.Notes+=" Use the emission-nebula filter; broadband galaxies/reflectors should not use it.";if(brightCore)guide.Notes+=" Orion's bright core can saturate; consider a separate shorter-exposure set if your capture mode supports it.";if(b>=7&&faint)guide.Notes+=" Urban sky is a poor match for faint reflection/dark dust; a darker site is preferable.";if(night.Illum>.65)guide.Notes+=" Bright Moon adds background; these Bortle values describe the baseline, not tonight's moonlight.";
        if(guide.MaxHours.HasValue){double visible=(pick.End-pick.Start).TotalHours;if(guide.MinHours>visible)guide.Notes+=" This goal needs multiple nights in the displayed visibility window.";guide.Notes+=" Total means retained exposure, excluding rejected frames, dithering and overhead.";}
        if(device!=null&&device.Id.StartsWith("ASI99")){guide.Exposure="SWIR: calibrate exposure for your spectral band";guide.Integration="Not estimated for SWIR cameras";guide.SubSeconds=null;guide.MinHours=null;guide.MaxHours=null;guide.Beginner=false;guide.Difficulty="Specialist SWIR setup";guide.Notes="Visible-light Bortle exposure and integration rules do not apply to this SWIR camera. Use spectral-band-specific sky and sensor measurements. "+EquipmentLibrary.ProfileNote(rig);}
        guide.Details=target.Name+"\n"+guide.Difficulty+" (equipment / sky heuristic)\n\n"+guide.Sky+"\n"+(sky==null?"No matching location sample; enter the map's value for this site.":sky.Source+"\n"+(sky.Sqm.HasValue?"SQM "+sky.Sqm.Value.ToString("0.00")+" mag/arcsec² · ":"")+"within "+sky.RadiusKm.ToString("0.#")+" km of saved sample")+"\n\nExposure: "+guide.Exposure+"\nGain: "+guide.Gain+"\nGoal: "+guide.Integration+"\n\n"+guide.Notes+"\n\nUse only app-confirmed exposure choices for the selected smart telescope. Camera gain is a documented starting point where available; verify the driver and read mode. Bortle cannot determine an exact exposure or a guaranteed signal-to-noise ratio.";
        return guide;
    }
}
}



